html, body {
	height: 100%;
}

body {
	display: flex;
	flex-direction: column;
	overflow: hidden;
}

input[type=number],
input[type=text],
textarea {
	border: 1px solid #3a3a3a;
}

input[type=number]:focus,
input[type=number]:hover,
input[type=text]:focus,
input[type=text]:hover,
textarea:focus,
textarea:hover{
	outline: none;
	border-color: #5b9bd5;
	box-shadow: 0 0 0 1px rgba(3,161,252,.15);
}

input[type=checkbox]:focus-visible {
	outline: 1px solid #5b9bd5;
	outline-offset: 3px;
	box-shadow: 0 0 0 1px rgba(3,161,252,.15);
	border-radius: 1px;
}

.tab:focus-visible {
	outline: 1px solid #5b9bd5;
	outline-offset: -1px;
	box-shadow: 0 0 0 1px rgba(3,161,252,.15);
	z-index: 500;
}

a:focus-visible {
	outline: 1px solid #5b9bd5;
	outline-offset: 3px;
	box-shadow: 0 0 0 0px rgba(3,161,252,.15);
	border-radius: 1px;
}

.dlg_header_row {
	display: flex;
	align-items: flex-start;
	justify-content: space-between;
	gap: 12px;
}

.dlg_header_left {
	display: flex;
	align-items: flex-start;
	gap: 10px;
	min-width: 0;
}

.dlg_icon {
	display: inline-block;
	width: 64px;
	height: 64px;
	line-height: 0;
	position: relative;
	top: -8px;
	left: -6px;
}

.dlg_icon svg {
	display: block;
	width: 100%;
	height: 100%;
}

.dlg_titles {
	display: grid;
	gap: 4px;
	min-width: 0;
}

.dlg_main_title {
	font-weight: bold;
	font-size: 1.25rem;
	line-height: 1.2;
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.dlg_sub_title {
	line-height: 1.5;
	opacity: .9;
}

.dlg_header_right {
	white-space: nowrap;
	align-self: flex-start;
}

.tabs {
	display: flex;
	gap: 0;
	padding: 8px 0 0 0;
}

.tab {
	appearance: none;
	border: 1px solid #555;
	padding: 6px 10px;
	border-bottom: 1px solid transparent;
	border-radius: 6px 6px 0 0;
	cursor: pointer;
	font: inherit;
	font-weight: normal;
	position: relative;
	z-index: 1;
}

.tab + .tab {
	margin-left: -1px;
}

.tab.is-active::after {
	content: "";
	position: absolute;
	left: 0px;
	right: 0px;
	bottom: -1px;
	height: 1px;
	background: inherit;
}

.panels {
	border: 1px solid #555;
	border-radius: 0 6px 6px 6px;
	padding: 14px;
	flex: 1 1 auto;
	overflow: auto;
	position: relative;
	z-index: 0;
}

.panel {
	display: none;
}

.chk_row {
	display: flex;
	align-items: center;
	gap: 8px;
}

.form_grid {
	display: grid;
	grid-template-columns: 1fr;
	row-gap: 8px;
	column-gap: 12px;
	align-items: start;
}

.form_grid .label {
	align-self: start;
	margin-top: 6px;
}

.ctrl {
	margin-left: 0;
}

.ctrl input[type=number] {
	width: 100%;
	margin-top: 0px;
}

.chk_row input[type="checkbox"] {
    margin: 3px 0px 3px 0px;
}

.note {
	margin-top: 6px;
	opacity: .55;
}

.mtop08 {
	margin-top: 08px;
}

.mtop14 {
	margin-top: 14px;
}

.footer_bar {
	display: flex;
	gap: 10px;
	justify-content: flex-end;
	padding: 14px 0 16px 0;
	margin: 12px 0 10px 0;
	margin-top: auto;
	border-top: none;
}

.btn {
	appearance: none;
	display: inline-flex;
	align-items: center;
	gap: 8px;
	border: 1px solid;
	padding: 6px 12px;
	border-radius: 6px;
	cursor: pointer;
	font: inherit;
	background: transparent;
	width: 100px;
}

.btn:focus-visible {
	outline: none;
	box-shadow: 0 0 0 2px rgba(3,161,252,.15);
}

.btn svg {
	width: 16px;
	height: 16px;
}

.btn svg path {
	fill: none;
	stroke: currentColor;
	stroke-linecap: round;
	stroke-linejoin: round;
}

.btn_ok {
	border-color: #2e7d32;
	color: #2e7d32;
}

.btn_ok:hover,
.btn_ok:focus-visible {
	background: rgba(46,125,50,.12);
	box-shadow: 0 0 0 2px rgba(46,200,50,.15);
}

.btn_ok svg path {
	stroke-width: 2;
}

.btn_cancel {
	border-color: #b71c1c;
	color: #b71c1c;
}

.btn_cancel:hover,
.btn_cancel:focus-visible {
	background: rgba(183,28,28,.12);
	box-shadow: 0 0 0 2px rgba(200,28,28,.15);
}

.btn_cancel svg path {
	stroke-width: 3;
}

@media (max-width:560px) {
	.form_grid {
		grid-template-columns: 1fr;
	}
}

.panels,
.panel,
input,
select,
textarea {
	color-scheme: dark;
}

input[type=number],
input[type=text],
textarea {
	background-color: #2a2a2a;
	color: #e6e6e6;
}

input::placeholder,
textarea::placeholder {
	color: #9a9a9a;
	opacity: 1;
}

input[type=checkbox] {
	accent-color: #03a1fc;
}

.tab {
	color: #7a7a7a;
	border-color: #3a3a3a;
	background: #292929;
}

.tab:hover {
	background: #353535;
	color: #bbb;
}

.tab.is-active { 
	color: #fff; 
	background: #212121;
}

.panels {
	background: #212121; 
	border-color: #3a3a3a;
}

.footer_bar {
	border-top-color: #3c3c3c;
	background: #1e1e1e;
}

.btn_ok {
	border-color: #2e7d32;
	color: #2e7d32;
}

.btn_ok:hover {
	background: rgba(46,125,50,.12);
}

.btn_cancel {
	border-color: #b71c1c;
	color: #b71c1c;
}

.btn_cancel:hover {
	background: rgba(183,28,28,.12);
}

.panels,
.panel,
input,
select,
textarea {
	color-scheme: light;
}

